fn solve(n: i8) -> Vec<i8> {
    // Number of complete 7-day weeks in the period
    let weeks = n / 7;
    // Remaining days beyond those full weeks
    let r = n % 7;

    // Minimum additional days off in the leftover r days:
    // if r ≤ 5, you can place them all on workdays → 0 days off;
    // otherwise r − 5 of them must fall on days off.
    let min_extra = (r - 5).max(0);
    // Maximum additional days off in the leftover r days:
    // you can pick at most 2 days off, but not more than r days total
    let max_extra = r.min(2);

    // Total days off = 2 per full week, plus the extra from the remainder
    let min_days_off = 2 * weeks + min_extra;
    let max_days_off = 2 * weeks + max_extra;

    vec![min_days_off, max_days_off]
}

